import { tanstackStart } from '@tanstack/react-start/plugin/vite'
import { defineConfig } from 'vite'
import viteReact from '@vitejs/plugin-react'

export default defineConfig({
  server: {
    port: 8234,
  },
  plugins: [tanstackStart(), viteReact()],
})

import { createRouter } from '@tanstack/react-router'
import { routeTree } from './routeTree.gen'

export function getRouter() {
  const router = createRouter({
    routeTree,
    scrollRestoration: true,
  })

  return router
}

declare module '@tanstack/react-router' {
  interface Register {
    router: ReturnType<typeof getRouter>
  }
}

import type { ReactNode } from 'react'
import {
  HeadContent,
  Outlet,
  Scripts,
  createRootRoute,
} from '@tanstack/react-router'

export const Route = createRootRoute({
  head: () => ({
    meta: [
      {
        charSet: 'utf-8',
      },
      {
        name: 'viewport',
        content: 'width=device-width, initial-scale=1',
      },
      {
        title: 'TanStack Start Counter',
      },
    ],
  }),
  component: RootComponent,
})

function RootComponent() {
  return (
    <RootDocument>
      <Outlet />
    </RootDocument>
  )
}

function RootDocument({ children }: Readonly<{ children: ReactNode }>) {
  return (
    <html>
      <head>
        <HeadContent />
      </head>
      <body>
        {children}
        <Scripts />
      </body>
    </html>
  )
}

import { createFileRoute } from '@tanstack/react-router'
import { createServerFn } from '@tanstack/react-start'

// In-memory counter state on the server
let count = 0

// Server function to get the current count
const getCount = createServerFn({ method: 'GET' }).handler(() => {
  return count
})

// Server function to increment the counter and return the new value
const incrementCount = createServerFn({ method: 'POST' }).handler(() => {
  count += 1
  return count
})

export const Route = createFileRoute('/')({
  component: Home,
  loader: async () => await getCount(),
})

function Home() {
  const state = Route.useLoaderData()

  return (
    <div style={{ fontFamily: 'system-ui, sans-serif', padding: '2rem' }}>
      <h1>Count: {state}</h1>
      <button
        type="button"
        onClick={() => {
          incrementCount().then((newCount) => {
            // Update the loader data so the UI reflects the new count
            Route.useLoaderData
            // Re-run the loader to refresh the displayed count
            window.location.reload()
            void newCount
          })
        }}
      >
        Increment
      </button>
    </div>
  )
}

import { createFileRoute, useRouter } from '@tanstack/react-router'
import { createServerFn } from '@tanstack/react-start'

// In-memory counter state on the server
let count = 0

// Server function to get the current count
const getCount = createServerFn({ method: 'GET' }).handler(() => {
  return count
})

// Server function to increment the counter and return the new value
const incrementCount = createServerFn({ method: 'POST' }).handler(() => {
  count += 1
  return count
})

export const Route = createFileRoute('/')({
  component: Home,
  loader: async () => await getCount(),
})

function Home() {
  const router = useRouter()
  const state = Route.useLoaderData()

  return (
    <div style={{ fontFamily: 'system-ui, sans-serif', padding: '2rem' }}>
      <h1>Count: {state}</h1>
      <button
        type="button"
        onClick={() => {
          incrementCount().then(() => {
            router.invalidate()
          })
        }}
      >
        Increment
      </button>
    </div>
  )
}
